@page "/apply"
@using sv_38575405ec644847af71ca148a9fab82.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2 class="mb-4">Job Application</h2>

    @* ── Step Indicator Bar ── *@
    <nav class="step-bar mb-4">
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var label = StepLabels[i];
            var isCurrent = step == CurrentStep;
            var isCompleted = step < CurrentStep;
            var isFuture = step > CurrentStep;

            <button type="button"
                    class="step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                    disabled="@isFuture"
                    @onclick="() => GoToStep(step)">
                <span class="step-circle">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@label</span>
            </button>

            @if (i < StepLabels.Length - 1)
            {
                <div class="step-connector @(step < CurrentStep ? "completed" : "")"></div>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    @* ── Step 1: Personal Info ── *@
    @if (CurrentStep == 1)
    {
        <div class="card p-4">
            <h4>Personal Information</h4>
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="John Doe" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" placeholder="john@example.com" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_address" placeholder="123 Main St, City, State" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextFromStep1" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Validating…</span>
                    }
                    else
                    {
                        <span>Next &raquo;</span>
                    }
                </button>
            </div>
        </div>
    }

    @* ── Step 2: Work History ── *@
    @if (CurrentStep == 2)
    {
        <div class="card p-4">
            <h4>Work History</h4>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var idx = i;
                <div class="border rounded p-3 mb-3">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h6 class="mb-0">Position @(idx + 1)</h6>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                        }
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Company Name <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="_workEntries[idx].Company" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Job Title <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="_workEntries[idx].Title" />
                        </div>
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-4">
                            <label class="form-label">Start Date <span class="text-danger">*</span></label>
                            <input type="date" class="form-control" @bind="_workEntries[idx].StartDate" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">End Date</label>
                            <input type="date" class="form-control" @bind="_workEntries[idx].EndDate" disabled="@_workEntries[idx].IsCurrent" />
                        </div>
                        <div class="col-md-4 d-flex align-items-end mb-1">
                            <div class="form-check">
                                <input type="checkbox" class="form-check-input" id="current-@idx"
                                       @bind="_workEntries[idx].IsCurrent" />
                                <label class="form-check-label" for="current-@idx">Currently working here</label>
                            </div>
                        </div>
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Description</label>
                        <textarea class="form-control" rows="2" @bind="_workEntries[idx].Description"></textarea>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-primary" @onclick="NextFromStep2">Next &raquo;</button>
            </div>
        </div>
    }

    @* ── Step 3: References ── *@
    @if (CurrentStep == 3)
    {
        <div class="card p-4">
            <h4>References</h4>
