@code {
    private const int TotalSteps = 5;
    private const int CoverLetterMaxLength = 2000;

    private static readonly string[] StepLabels =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int CurrentStep { get; set; } = 1;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private bool _isValidating;

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = "";

    // Step 5
    private bool _isSubmitting;
    private bool _isSubmitted;
    private int _applicationId;

    private string? _errorMessage;

    // ── Navigation ──

    private void GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            _errorMessage = null;
            CurrentStep = step;
        }
    }

    private void NextStep()
    {
        _errorMessage = null;
        if (CurrentStep < TotalSteps)
            CurrentStep++;
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        if (CurrentStep > 1)
            CurrentStep--;
    }

    // ── Step 1 Validation ──

    private async Task NextFromStep1()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
            string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(_email.Trim());
            if (!valid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
            NextStep();
        }
        finally
        {
            _isValidating = false;
        }
    }

    // ── Step 2 ──

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void NextFromStep2()
    {
        _errorMessage = null;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                _errorMessage = "Each position requires a company name, job title, and start date.";
                return;
            }
        }

        NextStep();
    }

    // ── Step 3 ──

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void NextFromStep3()
    {
        _errorMessage = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }

        NextStep();
    }

    // ── Submit ──

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _errorMessage = null;

        try
        {
            var personal = new PersonalInfo(_fullName.Trim(), _email.Trim(), _phone.Trim(), _address.Trim());

            var workEntries = _workEntries.Select(e =>
                new WorkEntry(e.Company.Trim(), e.Title.Trim(), e.StartDate,
                    e.IsCurrent ? null : e.EndDate, e.Description?.Trim() ?? "")).ToList();

            var refs = _references.Select(r =>
                new Reference(r.Name.Trim(), r.Relationship.Trim(), r.Email.Trim(), r.Phone.Trim())).ToList();

            var application = new JobApplication(personal, new WorkHistory(workEntries), refs, _coverLetter);

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _isSubmitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    // ── Mutable view-models for form binding ──

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

