@page "/apply"
@using sv_38575405ec644847af71ca148a9fab82.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2 class="mb-4">Job Application</h2>

    @* ── Step Indicator Bar ── *@
    <nav class="step-bar mb-4">
        @for (int i = 0; i < StepLabels.Length; i++)
        {
            var step = i + 1;
            var label = StepLabels[i];
            var isCurrent = step == CurrentStep;
            var isCompleted = step < CurrentStep;
            var isFuture = step > CurrentStep;

            <button type="button"
                    class="step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")"
                    disabled="@isFuture"
                    @onclick="() => GoToStep(step)">
                <span class="step-circle">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @step
                    }
                </span>
                <span class="step-label">@label</span>
            </button>

            @if (i < StepLabels.Length - 1)
            {
                <div class="step-connector @(step < CurrentStep ? "completed" : "")"></div>
            }
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    @* ── Step 1: Personal Info ── *@
    @if (CurrentStep == 1)
    {
        <div class="card p-4">
            <h4>Personal Information</h4>
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" placeholder="John Doe" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" placeholder="john@example.com" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" placeholder="(555) 123-4567" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_address" placeholder="123 Main St, City, State" />
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextFromStep1" disabled="@_isValidating">
                    @if (_isValidating)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Validating…</span>
                    }
                    else
                    {
                        <span>Next &raquo;</span>
                    }
                </button>
            </div>
        </div>
    }

    @* ── Step 2: Work History ── *@
    @if (CurrentStep == 2)
    {
        <div class="card p-4">
            <h4>Work History</h4>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var idx = i;
                <div class="border rounded p-3 mb-3">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h6 class="mb-0">Position @(idx + 1)</h6>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                        }
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Company Name <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="_workEntries[idx].Company" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Job Title <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="_workEntries[idx].Title" />
                        </div>
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-4">
                            <label class="form-label">Start Date <span class="text-danger">*</span></label>
                            <input type="date" class="form-control" @bind="_workEntries[idx].StartDate" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">End Date</label>
                            <input type="date" class="form-control" @bind="_workEntries[idx].EndDate" disabled="@_workEntries[idx].IsCurrent" />
                        </div>
                        <div class="col-md-4 d-flex align-items-end mb-1">
                            <div class="form-check">
                                <input type="checkbox" class="form-check-input" id="current-@idx"
                                       @bind="_workEntries[idx].IsCurrent" />
                                <label class="form-check-label" for="current-@idx">Currently working here</label>
                            </div>
                        </div>
                    </div>
                    <div class="mb-2">
                        <label class="form-label">Description</label>
                        <textarea class="form-control" rows="2" @bind="_workEntries[idx].Description"></textarea>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-primary" @onclick="NextFromStep2">Next &raquo;</button>
            </div>
        </div>
    }

    @* ── Step 3: References ── *@
    @if (CurrentStep == 3)
    {
        <div class="card p-4">
            <h4>References</h4>
            @for (int i = 0; i < _references.Count; i++)
            {
                var idx = i;
                <div class="border rounded p-3 mb-3">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h6 class="mb-0">Reference @(idx + 1)</h6>
                        @if (_references.Count > 2)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(idx)">Remove</button>
                        }
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Name <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="_references[idx].Name" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Relationship <span class="text-danger">*</span></label>
                            <input class="form-control" @bind="_references[idx].Relationship" placeholder="e.g., Former Manager" />
                        </div>
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Email <span class="text-danger">*</span></label>
                            <input type="email" class="form-control" @bind="_references[idx].Email" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Phone <span class="text-danger">*</span></label>
                            <input type="tel" class="form-control" @bind="_references[idx].Phone" />
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-primary" @onclick="NextFromStep3">Next &raquo;</button>
            </div>
        </div>
    }

    @* ── Step 4: Cover Letter ── *@
    @if (CurrentStep == 4)
    {
        <div class="card p-4">
            <h4>Cover Letter</h4>
            <div class="mb-2">
                <textarea class="form-control" rows="10" @bind="_coverLetter" @bind:event="oninput"
                          maxlength="@CoverLetterMaxLength" placeholder="Tell us why you're a great fit…"></textarea>
            </div>
            <div class="text-muted mb-3">@_coverLetter.Length / @CoverLetterMaxLength characters</div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next &raquo;</button>
            </div>
        </div>
    }

    @* ── Step 5: Review & Submit ── *@
    @if (CurrentStep == 5 && !_isSubmitted)
    {
        <div class="card p-4">
            <h4>Review &amp; Submit</h4>

            @* Personal Info *@
            <div class="review-section mb-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Personal Information</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(1)'>Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Full Name</dt><dd class="col-sm-9">@_fullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                </dl>
            </div>
            <hr />

            @* Work History *@
            <div class="review-section mb-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(2)'>Edit</button>
                </div>
                @foreach (var entry in _workEntries)
                {
                    <div class="mb-2 ms-2">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1">@entry.Description</p>
                        }
                    </div>
                }
            </div>
            <hr />

            @* References *@
            <div class="review-section mb-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>References</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(3)'>Edit</button>
                </div>
                @foreach (var r in _references)
                {
                    <div class="mb-2 ms-2">
                        <strong>@r.Name</strong> — @r.Relationship<br />
                        <small class="text-muted">@r.Email · @r.Phone</small>
                    </div>
                }
            </div>
            <hr />

            @* Cover Letter *@
            <div class="review-section mb-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Cover Letter</h5>
                    <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(4)'>Edit</button>
                </div>
                <p class="ms-2" style="white-space: pre-wrap;">@_coverLetter</p>
            </div>

            <div class="d-flex justify-content-between mt-3">
                <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <span>Submitting…</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        </div>
    }

    @* ── Confirmation ── *@
    @if (_isSubmitted)
    {
        <div class="card p-4 text-center">
            <div class="mb-3" style="font-size:3rem;color:green;">&#10003;</div>
            <h3>Application Submitted!</h3>
            <p class="lead">Your application ID is <strong>#@_applicationId</strong>.</p>
            <p class="text-muted">We'll review your application and get back to you soon.</p>
        </div>
    }
</div>

@code {
    private const int TotalSteps = 5;
    private const int CoverLetterMaxLength = 2000;

    private static readonly string[] StepLabels =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int CurrentStep { get; set; } = 1;

    // Step 1
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private bool _isValidating;

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = "";

    // Step 5
    private bool _isSubmitting;
    private bool _isSubmitted;
    private int _applicationId;

    private string? _errorMessage;

    // ── Navigation ──

    private void GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            _errorMessage = null;
            CurrentStep = step;
        }
    }

    private void NextStep()
    {
